{"command": "python3 -c "
import sys, json, os
base = 'benchmark/skillsbench/tasks/civ6-adjacency-optimizer'
sys.path.insert(0, f'{base}/tests/src')
sys.path.insert(0, f'{base}/tests/tools')
from hex_utils import hex_distance, get_neighbors, get_tiles_in_range
from civ6map_to_scenario import convert_civ6map
from placement_rules import Tile, DistrictType, DISTRICT_NAME_MAP

DESTRUCTIBLE_FEATURES = {'FEATURE_FOREST', 'FEATURE_JUNGLE', 'FEATURE_MARSH'}

from dataclasses import dataclass
@dataclass
class AdjacencyRule:
    sources: list
    bonus_per: int = 1
    count_required: int = 1

DISTRICT_ADJACENCY_RULES = {
    DistrictType.CAMPUS: [
        AdjacencyRule(['FEATURE_GEOTHERMAL_FISSURE'], 2, 1),
        AdjacencyRule(['FEATURE_REEF'], 2, 1),
        AdjacencyRule(['MOUNTAIN'], 1, 1),
        AdjacencyRule(['GOVERNMENT_PLAZA'], 1, 1),
        AdjacencyRule(['FEATURE_JUNGLE'], 1, 2),
        AdjacencyRule(['DISTRICT'], 1, 2),
    ],
    DistrictType.HOLY_SITE: [
        AdjacencyRule(['NATURAL_WONDER'], 2, 1),
        AdjacencyRule(['MOUNTAIN'], 1, 1),
        AdjacencyRule(['GOVERNMENT_PLAZA'], 1, 1),
        AdjacencyRule(['FEATURE_FOREST'], 1, 2),
        AdjacencyRule(['DISTRICT'], 1, 2),
    ],
    DistrictType.COMMERCIAL_HUB: [
        AdjacencyRule(['HARBOR'], 2, 1),
        AdjacencyRule(['GOVERNMENT_PLAZA'], 1, 1),
        AdjacencyRule(['DISTRICT'], 1, 2),
    ],
    DistrictType.INDUSTRIAL_ZONE: [
        AdjacencyRule(['AQUEDUCT', 'BATH', 'DAM', 'CANAL'], 2, 1),
        AdjacencyRule(['QUARRY'], 1, 1),
        AdjacencyRule(['STRATEGIC_RESOURCE'], 1, 1),
        AdjacencyRule(['GOVERNMENT_PLAZA'], 1, 1),
        AdjacencyRule(['MINE'], 1, 2),
        AdjacencyRule(['LUMBER_MILL'], 1, 2),
        AdjacencyRule(['DISTRICT'], 1, 2),
    ],
    DistrictType.HARBOR: [
        AdjacencyRule(['CITY_CENTER'], 2, 1),
        AdjacencyRule(['COASTAL_RESOURCE'], 1, 1),
        AdjacencyRule(['GOVERNMENT_PLAZA'], 1, 1),
        AdjacencyRule(['DISTRICT'], 1, 2),
    ],
}

def get_adjacency_bonus(district_type, x, y, tiles, placements):
    tile = tiles.get((x, y))
    if tile is None:
        return 0
    total = 0
    if district_type == DistrictType.COMMERCIAL_HUB and tile.has_river:
        total += 2
    rules = DISTRICT_ADJACENCY_RULES.get(district_type, [])
    for rule in rules:
        count = 0
        for nx, ny in get_neighbors(x, y):
            ntile = tiles.get((nx, ny))
            if ntile is None:
                continue
            for source in rule.sources:
                matched = False
                if source == 'MOUNTAIN' and ntile.is_mountain:
                    count += 1; matched = True
                elif ntile.feature and ntile.feature == source:
                    count += 1; matched = True
                elif ntile.feature and source in ntile.feature:
                    count += 1; matched = True
                elif source == 'DISTRICT' and (nx, ny) in placements:
                    count += 1; matched = True
                elif source == 'CITY_CENTER' and placements.get((nx, ny)) == DistrictType.CITY_CENTER:
                    count += 1; matched = True
                elif source == 'HARBOR' and placements.get((nx, ny)) == DistrictType.HARBOR:
                    count += 1; matched = True
                elif source in ('AQUEDUCT', 'BATH', 'DAM', 'CANAL') and placements.get((nx, ny)) and placements.get((nx, ny)).name == source:
                    count += 1; matched = True
                if matched:
                    break
        if count == 0:
            continue
        if rule.count_required == 1:
            total += count * rule.bonus_per
        else:
            total += (count // rule.count_required) * rule.bonus_per
    return total

def apply_destruction(tiles, placements):
    modified = {}
    for coord, tile in tiles.items():
        if coord in placements:
            dtype = placements[coord]
            if dtype != DistrictType.CITY_CENTER:
                modified[coord] = Tile(
                    x=tile.x, y=tile.y, terrain=tile.terrain,
                    feature=None if tile.feature in DESTRUCTIBLE_FEATURES else tile.feature,
                    is_hills=tile.is_hills, is_floodplains=tile.is_floodplains,
                    river_edges=list(tile.river_edges), river_names=list(tile.river_names),
                    resource=None if tile.resource_type == 'BONUS' else tile.resource,
                    resource_type=None if tile.resource_type == 'BONUS' else tile.resource_type,
                    improvement=None,
                )
            else:
                modified[coord] = tile
        else:
            modified[coord] = tile
    return modified

map_path = f'{base}/environment/data/maps/e2e_test_case_0.Civ6Map'
map_data = convert_civ6map(map_path)
tiles = {}
for t in map_data['tiles']:
    tile = Tile(
        x=t['x'], y=t['y'], terrain=t['terrain'], feature=t.get('feature'),
        is_hills=t.get('is_hills', False), is_floodplains=t.get('is_floodplains', False),
        river_edges=t.get('river_edges', []), river_names=t.get('river_names', []),
        resource=t.get('resource'), resource_type=t.get('resource_type'),
        improvement=t.get('improvement'),
    )
    tiles[(tile.x, tile.y)] = tile

solution = {
    'city_center': [22, 15],
    'placements': {
        'CAMPUS': [21, 14],
        'INDUSTRIAL_ZONE': [23, 16],
        'AQUEDUCT': [23, 15],
        'DAM': [24, 16],
        'CANAL': [22, 16],
        'COMMERCIAL_HUB': [23, 14],
        'NEIGHBORHOOD': [[22, 17], [23, 17], [22, 13], [22, 14], [23, 13], [24, 14]]
    }
}

city_center = (22, 15)
placements = {city_center: DistrictType.CITY_CENTER}
for district_name, coords in solution['placements'].items():
    dtype = DISTRICT_NAME_MAP[district_name]
    if isinstance(coords[0], list):
        for x, y in coords:
            placements[(x, y)] = dtype
    else:
        x, y = coords
        placements[(x, y)] = dtype

modified = apply_destruction(tiles, placements)
total = 0
per_district = {}
for (x, y), dtype in placements.items():
    if dtype == DistrictType.CITY_CENTER:
        continue
    bonus = get_adjacency_bonus(dtype, x, y, modified, placements)
    total += bonus
    key = f'{dtype.name}@({x},{y})'
    per_district[key] = bonus

adjacency_bonuses = {}
for key, bonus in per_district.items():
    dtype_name = key.split('@')[0]
    adjacency_bonuses[dtype_name] = adjacency_bonuses.get(dtype_name, 0) + bonus

solution['adjacency_bonuses'] = adjacency_bonuses
solution['total_adjacency'] = total

print(f'Total adjacency: {total}')
print(f'Per-district: {adjacency_bonuses}')
print(f'Sum of bonuses: {sum(adjacency_bonuses.values())}')
print()
print(json.dumps(solution, indent=2))

os.makedirs('/tmp/civ6_output', exist_ok=True)
with open('/tmp/civ6_output/scenario_3.json', 'w') as f:
    json.dump(solution, f, indent=2)
print()
print('Written to /tmp/civ6_output/scenario_3.json')
"
