{"content": "// Global state
let selectedTicker = null;
let stockData = [];

// Color scale for sectors - 5 distinct colors
const sectorColors = {
    'Energy': '#e41a1c',
    'Financial': '#377eb8',
    'Industry': '#4daf4a',
    'Information Technology': '#984ea3',
    'ETF': '#ff7f00'
};

// ETF tickers list for filtering
const etfTickers = new Set(['SPY', 'VOO', 'QQQ', 'GLD', 'XLF', 'VWO', 'XLU', 'XLV', 'VEA', 'VTV']);

// Format market cap into readable string
function formatMarketCap(value) {
    if (!value || isNaN(value) || value === 0) return 'N/A';
    if (value >= 1e12) return '$' + (value / 1e12).toFixed(2) + 'T';
    if (value >= 1e9) return '$' + (value / 1e9).toFixed(2) + 'B';
    if (value >= 1e6) return '$' + (value / 1e6).toFixed(2) + 'M';
    return '$' + value.toFixed(2);
}

// Load and visualize data
d3.csv('data/stock-descriptions.csv').then(data => {
    // Parse market cap as number and filter to 50 entries
    data.forEach(d => {
        d.marketCap = +d.marketCap || 0;
    });

    stockData = data;

    // Create visualizations
    createBubbleChart(data);
    createTable(data);
    createLegend();
}).catch(err => {
    console.error('Failed to load data:', err);
    document.body.innerHTML = '<h1>Error loading stock data</h1><p>' + err.message + '</p>';
});

function createLegend() {
    const legend = d3.select('#legend');

    Object.entries(sectorColors).forEach(([sector, color]) => {
        const item = legend.append('div')
            .attr('class', 'legend-item');

        item.append('div')
            .attr('class', 'legend-color')
            .style('background-color', color);

        item.append('span')
            .text(sector);
    });
}

function createBubbleChart(data) {
    const width = 700;
    const height = 600;

    const svg = d3.select('#bubble-chart')
        .attr('width', width)
        .attr('height', height);

    // Calculate radius based on market cap
    const maxMarketCap = d3.max(data, d => d.marketCap || 1);
    const radiusScale = d3.scaleSqrt()
        .domain([0, maxMarketCap])
        .range([10, 55]);

    // Define cluster centers for each sector
    // Arranged in a circle around the center so clusters are close together and centered
    const cx = width / 2;
    const cy = height / 2;
    const clusterRadius = 140;

    const sectorNames = ['Energy', 'Financial', 'Industry', 'Information Technology', 'ETF'];

    // Place sectors evenly around a circle
    const sectorCenters = {};
    sectorNames.forEach((sector, i) => {
        const angle = (i / sectorNames.length) * 2 * Math.PI - Math.PI / 2;
        sectorCenters[sector] = {
            x: cx + Math.cos(angle) * clusterRadius,
            y: cy + Math.sin(angle) * clusterRadius
        };
    });

    // Prepare nodes with radius and cluster center
    const nodes = data.map(d => ({
        ...d,
        radius: d.sector === 'ETF' ? 15 : radiusScale(d.marketCap || 0),
        x: cx,
        y: cy,
        clusterX: sectorCenters[d.sector].x,
        clusterY: sectorCenters[d.sector].y
    }));

    // Create force simulation with sector-based clustering
    const simulation = d3.forceSimulation(nodes)
        .force('charge', d3.forceManyBody().strength(-5))
        .force('collision', d3.forceCollide().radius(d => d.radius + 2))
        .force('x', d3.forceX(d => d.clusterX).strength(0.08))
        .force('y', d3.forceY(d => d.clusterY).strength(0.08));

    // Create bubbles
    const bubbles = svg.selectAll('.bubble')
        .data(nodes)
        .enter()
        .append('circle')
        .attr('class', 'bubble')
        .attr('r', d => d.radius)
        .attr('fill', d => sectorColors[d.sector])
        .attr('opacity', 0.75)
        .on('click', function(event, d) {
            selectStock(d.ticker);
        })
        .on('mouseover', function(event, d) {
            showTooltip(event, d);
        })
        .on('mouseout', hideTooltip);

    // Create labels for bubbles
    const labels = svg.selectAll('.bubble-label')
        .data(nodes)
        .enter()
        .append('text')
        .attr('class', 'bubble-label')
        .text(d => d.ticker)
        .style('font-size', d => Math.min(d.radius * 0.55, 12) + 'px')
        .attr('dominant-baseline', 'central');

    // Update positions on tick with boundary constraints
    simulation.on('tick', () => {
        // Constrain bubbles to stay within SVG bounds
        nodes.forEach(d => {
            d.x = Math.max(d.radius + 3, Math.min(width - d.radius - 3, d.x));
            d.y = Math.max(d.radius + 3, Math.min(height - d.radius - 3, d.y));
        });

        bubbles
            .attr('cx', d => d.x)
            .attr('cy', d => d.y);

        labels
            .attr('x', d => d.x)
            .attr('y', d => d.y);
    });
}

function createTable(data) {
    const tbody = d3.select('#stock-table tbody');

    const rows = tbody.selectAll('tr')
        .data(data)
        .enter()
        .append('tr')
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    rows.append('td').text(d => d.ticker);
    rows.append('td').text(d => d['full name'] || d.ticker);
    rows.append('td').text(d => d.sector);
    rows.append('td').text(d => {
        if (d.marketCap === 0 || d.sector === 'ETF') return 'N/A';
        return formatMarketCap(d.marketCap);
    });
}

function selectStock(ticker) {
    selectedTicker = selectedTicker === ticker ? null : ticker;

    // Update bubble selection
    d3.selectAll('.bubble')
        .classed('selected', d => d.ticker === selectedTicker);

    // Update table selection
    d3.selectAll('#stock-table tbody tr')
        .classed('selected', d => d.ticker === selectedTicker);
}

function showTooltip(event, d) {
    // Do not show tooltips for ETFs (no marketCap/country/website data)
    if (d.sector === 'ETF') {
        return;
    }
    const tooltip = d3.select('#tooltip');

    tooltip
        .classed('visible', true)
        .html(
            '<strong>' + d.ticker + '</strong><br/>' +
            (d['full name'] || 'N/A') + '<br/>' +
            'Sector: ' + d.sector
        )
        .style('left', (event.pageX + 10) + 'px')
        .style('top', (event.pageY - 10) + 'px');
}

function hideTooltip() {
    d3.select('#tooltip').classed('visible', false);
}
