{"content": "#!/usr/bin/env python3
"""Enterprise information search - agent solving the 3 questions."""
import json
import re
from pathlib import Path
from datetime import datetime, timedelta
from typing import Any, Dict, List, Set, Optional
from urllib.parse import urlparse

DATA_ROOT = Path("/home/liangfeng/git/hermes-agent/benchmark/skillsbench/tasks/enterprise-information-search/local_env/DATA")
OUT_PATH = Path("/home/liangfeng/git/hermes-agent/benchmark/skillsbench/tasks/enterprise-information-search/local_env/answer.json")
EID_RE = re.compile(r"\beid_[0-9a-f]{8}\b", re.IGNORECASE)
URL_RE = re.compile(r"https?://[^\s<>()\"']+")

# ==================== Helper functions ====================

def load_json(p: Path) -> Any:
    with p.open("r", encoding="utf-8") as f:
        return json.load(f)

def parse_iso(ts: str) -> datetime:
    return datetime.strptime(ts, "%Y-%m-%dT%H:%M:%S")

def extract_eids(text: str) -> Set[str]:
    return {m.lower() for m in EID_RE.findall(text or "")}

def is_eid(text: str) -> bool:
    return text.strip().lower().startswith("eid_")


# ==================== Q1: CoachForce Market Research Report ====================

def find_market_research_report(prod: Dict) -> Dict:
    """Find the Market Research Report in the product's documents."""
    docs = prod.get("documents", [])
    for d in docs:
        if isinstance(d, dict) and d.get("type", "").strip().lower() == "market research report":
            return d
    # fallback: search in JSON text
    for d in docs:
        if isinstance(d, dict):
            if "market research report" in json.dumps(d, ensure_ascii=False).lower():
                return d
    raise RuntimeError("Cannot find Market Research Report document.")


def solve_q1() -> List[str]:
    """Find employee IDs of authors and key reviewers of Market Research Report for CoachForce."""
    prod = load_json(DATA_ROOT / "products" / "CoachForce.json")
    report = find_market_research_report(prod)
    report_id = str(report.get("id") or "")
    report_link = str(report.get("document_link") or report.get("link") or "")

    # Step 1: Get author
    author = str(report.get("author", "")).strip().lower()
    eids: Set[str] = {author} if author.startswith("eid_") else set()

    # Step 2: Get reviewers from document
    reviewers = report.get("reviewers", report.get("key_reviewers", report.get("requested_reviewers", [])))
    if isinstance(reviewers, list):
        for r in reviewers:
            if isinstance(r, str) and r.lower().startswith("eid_"):
                eids.add(r.lower())
            elif isinstance(r, dict):
                rid = str(r.get("employee_id", r.get("id", r.get("user_id", "")))).lower()
                if rid.startswith("eid_"):
                    eids.add(rid)

    # Step 3: Find Slack announcement and nearby discussion participants
    slack = prod.get("slack", [])
    if isinstance(slack, list):
        announce = None
        for s in slack:
            if not isinstance(s, dict):
                continue
            try:
                txt = s["Message"]["User"]["text"]
            except Exception:
                continue
            if (report_link and report_link in txt) or (report_id and report_id in txt):
                announce = s
                break
        if announce is None:
            for s in slack:
                if not isinstance(s, dict):
                    continue
                try:
                    txt = s["Message"]["User"]["text"]
                except Exception:
                    continue
                if "market research report" in (txt or "").lower():
                    announce = s
                    break
        if announce is not None:
            channel = announce.get("Channel", {}).get("name")
            t0 = parse_iso(announce["Message"]["User"]["timestamp"])
            t_start = t0 - timedelta(minutes=5)
            t_end = t0 + timedelta(hours=1)
            for s in slack:
                if not isinstance(s, dict):
                    continue
                try:
                    if s.get("Channel", {}).get("name") != channel:
                        continue
                    ts = parse_iso(s["Message"]["User"]["timestamp"])
                    if not (t_start <= ts <= t_end):
                        continue
                    uid = str(s["Message"]["User"].get("userId") or "").lower()
                    if uid.startswith("eid_"):
                        eids.add(uid)
                    eids |= extract_eids(s["Message"]["User"].get("text", ""))
                except Exception:
                    continue

    # Step 4: Review meeting transcripts
    transcripts = prod.get("meeting_transcripts", [])
    if isinstance(transcripts, list):
        for mt in transcripts:
            if not isinstance(mt, dict):
                continue
            transcript = mt.get("transcript", "")
            if not isinstance(transcript, str):
                continue
            low = transcript.lower()
            if "market research report" not in low:
                continue
            # participants
            parts = mt.get("participants", [])
            if isinstance(parts, list):
                for p in parts:
                    if isinstance(p, str) and p.lower().startswith("eid_"):
                        eids.add(p.lower())
            # also extract eids from transcript text
            eids |= extract_eids(transcript)

    return sorted(eids)


# ==================== Q2: PersonalizeForce competitor insights ====================

def get_slack_user_text(item: Any) -> tuple:
    if not isinstance(item, dict):
        return None, ""
    try:
        user = item["Message"]["User"]
        uid = user.get("userId")
        txt = user.get("text", "")
        uid = uid.lower() if isinstance(uid, str) else None
        txt = txt if isinstance(txt, str) else ""
        return uid, txt
    except Exception:
        return None, ""

COMP_NAME_PATTERNS = [
    re.compile(r"\babout\s+([A-Z][A-Za-z0-9_-]{2,})\b[^.\n]{0,80}\bcompetitor product\b", re.IGNORECASE),
    re.compile(r"\b([A-Z][A-Za-z0-9_-]{2,})\s*,\s*a competitor product\b", re.IGNORECASE),
]

INFO_TERMS = [
    "offers","offer","integrates","integrate","uses","use","allows","allow",
    "support","supports","capabilities","capability","dashboard","analytics",
    "predictive","segmentation","segments","a/b testing","recommendation",
    "recommendations","personalization","real-time","dynamic","mapping","journey",
    "customizable","customize","algorithms","multi-channel","conversion","engagement",
    "weakness","weaknesses","challenge","challenges","issue","issues","problem","problems",
    "barrier","steep","learning curve","struggles","accuracy","inconsisten","dependency",
    "unreliable","cost","setup","complex","integration process","limited support","data input",
]

THANK_PAT = re.compile(r"\b(thanks|thank you|super helpful|keep these|keep this|keep in mind)\b", re.IGNORECASE)
SPECIFIC_TERMS = [
    "steep","learning curve","accuracy","setup cost","cost","complex",
    "integration process","limited","data input","dependency","unreliable",
    "predictive","segmentation","dashboard","multi-channel","customiz",
    "a/b testing","crm","marketing platforms","real-time","journey mapping","social media",
]


def extract_competitor_names(slack_items: list) -> Set[str]:
    names: Set[str] = set()
    for it in slack_items:
        _, text = get_slack_user_text(it)
        if not text:
            continue
        for pat in COMP_NAME_PATTERNS:
            for m in pat.finditer(text):
                names.add(m.group(1))
    return names


def is_insight_statement(text: str) -> bool:
    if not text:
        return False
    tl = text.lower()
    if "http" in tl and len(tl) < 120 and ("demo" in tl or "take a look" in tl):
        return False
    if "?" in text:
        return False
    if not (any(t in tl for t in INFO_TERMS) or any(t in tl for t in SPECIFIC_TERMS)):
        return False
    if THANK_PAT.search(text) and not any(st in tl for st in SPECIFIC_TERMS):
        return False
    return True


def solve_q2() -> List[str]:
    """Find employee IDs of team members who provided competitor insights."""
    prod = load_json(DATA_ROOT / "products" / "PersonalizeForce.json")
    team = {e.lower() for e in (prod.get("team", []) or []) if isinstance(e, str) and is_eid(e)}
    slack_items = prod.get("slack", []) if isinstance(prod.get("slack", []), list) else []
    competitor_names = extract_competitor_names(slack_items)
    comp_lowers = {c.lower() for c in competitor_names}

    eids: Set[str] = set()
    for it in slack_items:
        uid, text = get_slack_user_text(it)
        if not uid or not uid.startswith("eid_"):
            continue
        tl = text.lower()
        mentions_comp = ("competitor product" in tl) or any(c in tl for c in comp_lowers)
        if mentions_comp and is_insight_statement(text):
            if not team or uid in team:
                eids.add(uid)
    return sorted(eids)


# ==================== Q3: Competitor demo URLs ====================

def _iter_strings(obj: Any):
    if isinstance(obj, dict):
        for v in obj.values():
            yield from _iter_strings(v)
    elif isinstance(obj, list):
        for v in obj:
            yield from _iter_strings(v)
    elif isinstance(obj, str):
        yield obj


def solve_q3() -> List[str]:
    """Find demo URLs for competitor products."""
    prod = load_json(DATA_ROOT / "products" / "PersonalizeForce.json")
    candidates = set()
    # Check urls field
    for u in prod.get("urls", []) or []:
        if isinstance(u, dict) and isinstance(u.get("link"), str):
            candidates.add(u["link"].strip())
    # Extract from all strings
    for s in _iter_strings(prod):
        for m in URL_RE.findall(s):
            candidates.add(m.strip().rstrip(".,;:!?"))
    # Filter for demo URLs
    def is_demo_url(url: str) -> bool:
        try:
            p = urlparse(url)
        except Exception:
            return False
        if p.scheme not in ("http", "https"):
            return False
        host = p.netloc.lower()
        path = p.path.lower()
        if "sf-internal.slack.com" in host or "personalizeforce" in host:
            return False
        return "/demo" in path or path.endswith("demo") or "demo" in url.lower()

    demo_urls = sorted({u for u in candidates if is_demo_url(u)})
    # Filter to competitor domains
    competitor_domains = {"personaai.com", "smartsuggest.com", "tailorai.com"}
    demo_urls = [u for u in demo_urls if urlparse(u).netloc.lower() in competitor_domains]
    return demo_urls


# ==================== Main ====================

def main():
    results = {}
    for qk, solver in [("q1", solve_q1), ("q2", solve_q2), ("q3", solve_q3)]:
        answer = solver()
        results[qk] = {"answer": answer, "tokens": 0}
        print(f"{qk}: {answer}")

    # Save to output file
    OUT_PATH.parent.mkdir(parents=True, exist_ok=True)
    with OUT_PATH.open("w", encoding="utf-8") as f:
        json.dump(results, f, indent=2, ensure_ascii=False)
    print(f"\nResults saved to {OUT_PATH}")


if __name__ == "__main__":
    main()
