from rdkit import Chem, DataStructs
from rdkit.Chem import AllChem
from rdkit import RDLogger
RDLogger.DisableLog('rdApp.*')

# The test expected results for Glucose show weird molecules with identical similarity.
# This suggests those molecules might resolve to SAME PubChem CID.
# Let's check CIDs.

def get_compound_info(name):
    try:
        compounds = pcp.get_compounds(name, 'name')
    except Exception as e:
        print(f"Error looking up {name}: {e}")
        return None
    if not compounds:
        return None
    result = []
    for c in compounds[:3]:
        result.append({'cid': c.cid, 'smiles': c.smiles, 'name': c.iupac_name if hasattr(c, 'iupac_name') else 'N/A'})
    return result

# Check what PubChem returns for key molecules
names = ['Glucose', 'Galactose', 'Ribose', 'Sucrose', 'Fructose', 
         'Cortisol', 'Morphine', 'Serine', 'Ethanol', 'Estradiol']

for name in names:
    results = get_compound_info(name)
    print(f"\n{name}: CID={results[0]['cid'] if results else 'N/A'}")
    if results:
        print(f"  SMILES (first 80): {results[0]['smiles'][:80]}")
