    10|}
    11|
    12|# Install dependencies
    13|npm install
    14|npm install -D tailwindcss postcss autoprefixer @tailwindcss/postcss
    15|pip3 install --break-system-packages playwright
    16|playwright install chromium
    17|
    18|# Make sure port 3000 is free
    19|kill_port_3000
    20|
    21|# Start app for BEFORE measurement
    22|npm run dev &
    23|DEV_PID=$!
    24|
    25|# Wait for server to be ready (poll until HTTP 200)
    26|echo "Waiting for dev server to start..."
    27|for i in $(seq 1 60); do
    28|  if curl -s -o /dev/null -w "%{http_code}" http://localhost:3000 2>/dev/null | grep -q "200"; then
    29|    echo "Dev server ready"
    30|    break
    31|  fi
    32|  sleep 1
    33|done
    34|
    35|# Measure BEFORE CLS using inline Python
    36|python3 << 'MEASURE_BEFORE'
    37|from playwright.sync_api import sync_playwright
    38|import json
    39|
    40|with sync_playwright() as p:
    41|    browser = p.chromium.launch(headless=True)
    42|    page = browser.new_page()
    43|
    44|    # Inject CLS observer with correct session window calculation
    45|    page.add_init_script("""
    46|        window.__cls = 0;
    47|        window.__shifts = [];
    48|        let currentWindowScore = 0;
    49|        let windowStart = 0;
    50|        let lastShiftTime = 0;
    51|
    52|        new PerformanceObserver((list) => {
    53|            for (const entry of list.getEntries()) {
    54|                if (entry.hadRecentInput) continue;
    55|
    56|                const t = entry.startTime / 1000; // seconds
    57|
    58|                // New window if: first shift, >1s gap, or >5s window
    59|                const newWindow =
    60|                    windowStart === 0 ||
    61|                    (t - lastShiftTime) > 1 ||
    62|                    (t - windowStart) > 5;
    63|
    64|                if (newWindow) {
    65|                    currentWindowScore = 0;
    66|                    windowStart = t;
    67|                }
    68|
    69|                currentWindowScore += entry.value;
    70|                lastShiftTime = t;
    71|                window.__shifts.push({value: entry.value, sources: entry.sources?.length || 0});
    72|
    73|                // CLS = maximum session window score
    74|                if (currentWindowScore > window.__cls) {
    75|                    window.__cls = currentWindowScore;
    76|                }
    77|            }
    78|        }).observe({ type: 'layout-shift', buffered: true });
    79|    """)
    80|
    81|    page.goto("http://localhost:3000", wait_until="networkidle")
    82|
    83|    # Wait for late-loading content (banners at 1500ms, 1800ms)
    84|    page.wait_for_timeout(2500)
    85|
    86|    page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
    87|    page.wait_for_timeout(1000)
    88|    page.evaluate("window.scrollTo(0, 0)")
    89|    page.wait_for_timeout(1000)
    90|
    91|    cls = page.evaluate("window.__cls")
    92|    shifts = page.evaluate("window.__shifts")
    93|    browser.close()
    94|
    95|result = {"cls": round(cls, 3), "shifts": shifts}
    96|with open("/tmp/before.json", "w") as f:
    97|    json.dump(result, f)
    98|print(f"BEFORE CLS: {cls}")
    99|MEASURE_BEFORE
