   169|'use client';
   170|
   171|import { createContext, useContext, useState, ReactNode } from 'react';
   172|
   173|type Theme = 'light' | 'dark';
   174|
   175|const ThemeContext = createContext<{
   176|  theme: Theme;
   177|  toggleTheme: () => void;
   178|}>({ theme: 'light', toggleTheme: () => {} });
   179|
   180|export function useTheme() {
   181|  return useContext(ThemeContext);
   182|}
   183|
   184|export function ThemeProvider({ children }: { children: ReactNode }) {
   185|  const [theme, setTheme] = useState<Theme>('light');
   186|
   187|  const toggleTheme = () => {
   188|    const newTheme = theme === 'light' ? 'dark' : 'light';
   189|    setTheme(newTheme);
   190|    localStorage.setItem('theme', newTheme);
   191|    document.documentElement.setAttribute('data-theme', newTheme);
   192|    const el = document.getElementById('theme-wrapper');
