    12|/**
    13| * A simple bounded-job-friendly sink that writes one line per record to a single local file.
    14| */
    15|public class LineFileSink extends RichSinkFunction<String> {
    16|    private final String outputPath;
    17|    private transient BufferedWriter writer;
    18|
    19|    public LineFileSink(String outputPath) {
    20|        this.outputPath = outputPath;
    21|    }
    22|
    23|    @Override
    24|    public void open(Configuration parameters) throws Exception {
    25|        File file = new File(outputPath);
    26|        File parent = file.getParentFile();
    27|        if (parent != null && !parent.exists()) {
    28|            parent.mkdirs();
    29|        }
    30|        this.writer = new BufferedWriter(new FileWriter(file, StandardCharsets.UTF_8, false));
    31|    }
    32|
    33|    @Override
    34|    public void invoke(String value, Context context) throws Exception {
    35|        writer.write(value);
    36|        writer.newLine();
    37|    }
    38|
    39|    @Override
    40|    public void close() throws Exception {
    41|        if (writer != null) {
    42|            try {
    43|                writer.flush();
    44|                writer.close();
    45|            } catch (IOException ignored) {
    46|            } finally {
    47|                writer = null;
    48|            }
    49|        }
    50|    }
